package icepunk_backend.controller;
import icepunk_backend.dto.*; import icepunk_backend.model.User; import icepunk_backend.repository.UserRepository; import icepunk_backend.service.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
/** Formal DSA notices require a contact; anonymous community reports remain available without an account. */
@RestController public class ContentReportController { private final ContentReportService service; private final UserRepository users; private final AuthRateLimitService limits; private final ClientIpService clientIps; public ContentReportController(ContentReportService s,UserRepository u,AuthRateLimitService l,ClientIpService c){service=s;users=u;limits=l;clientIps=c;} @PostMapping("/reports") public ResponseEntity<ContentReportSubmissionResponse> create(Authentication a,HttpServletRequest request,@Valid @RequestBody CreateContentReportRequest r){User u=a==null?null:users.findByEmail(a.getName()).orElse(null); if(u==null)limits.checkAnonymousReportLimit(clientIps.getClientIp(request));else limits.checkReportLimit(u.getId());return ResponseEntity.status(HttpStatus.ACCEPTED).body(new ContentReportSubmissionResponse(service.create(u,r)));}}
